    total = 0
    for i, ch in enumerate(reversed(digits)):
        n = int(ch)
        if i % 2 == start_parity:
            n *= mult
            if n > 9:
                n -= sub
        total += n
    if formula == "a":
        return (10 - total % 10) % 10
    elif formula == "b":
        return total % 10
    elif formula == "c":
        return (9 - total % 10) % 10
    elif formula == "d":
        return total % 11
    elif formula == "e":
        return (11 - total % 11) % 11


